    "track sleep",
    "remind to stretch"
  ],
  "also_needed": [
    "log lifts"
  ],
  "jobs": [
    {
      "name": "log runs",
      "does": "Records the user's running activities.",
      "parts": [
        {
          "kind": "code-app",
          "search": ["fitness tracking app", "running log"]
        },
        {
          "kind": "data-template",
          "search": ["running log template", "fitness tracking spreadsheet"]
        }
      ]
    },
    {
      "name": "follow training plan",
      "does": "Provides a structured workout plan for the user.",
      "parts": [
        {
          "kind": "code-app",
          "search": ["personal trainer app", "training plan generator"]
        },
        {
          "kind": "data-template",
          "search": ["training plan template", "workout schedule"]
        }
      ]
    },
    {
      "name": "track weight",
      "does": "Monitors the user's weight over time.",
      "parts": [
        {
          "kind": "code-app",
          "search": ["weight tracker app", "body weight log"]
        },
        {
          "kind": "device",
          "search": ["smart scale", "wireless scale"]
        }
      ]
    },
    {
      "name": "track sleep",
      "does": "Records the user's sleep patterns and quality.",
      "parts": [
        {
          "kind": "code-app",
          "search": ["sleep tracker app", "sleep log"]
        },
        {
          "kind": "live-info",
          "search": ["sleep quality", "sleep duration"]
        }
      ]
    },
    {
      "name": "remind to stretch",
      "does": "Sends reminders to the user to perform stretching exercises.",
      "parts": [
        {
          "kind": "code-app",
          "search": ["reminder app", "stretch reminder"]
        },
        {
          "kind": "knowledge",
          "search": ["stretching exercises", "yoga poses"]
        }
      ]
    },
    {
      "name": "log lifts",
      "does": "Records the user's weightlifting activities.",
      "parts": [
        {
          "kind": "code-app",
          "search": ["fitness tracking app", "weightlifting log"]
        },
        {
          "kind": "data-template",
          "search": ["lifting log template", "weight training spreadsheet"]
        }
      ]
    }
  ]
}
